# Scope: def _chroma_has_documents
def _chroma_has_documents(store) -> bool:
    try:
        payload = store.get(limit=1)
    except TypeError:
        payload = store.get()
    except Exception:
        return False

    if not isinstance(payload, dict):
        return False
    ids = payload.get("ids") or []
    if isinstance(ids, list):
        return len(ids) > 0
    return bool(ids)

