# Scope: def _b64url_decode_text
def _b64url_decode_text(value: str) -> str:
    text = (value or "").strip()
    if not text:
        return ""
    try:
        padding = "=" * ((4 - len(text) % 4) % 4)
        raw = base64.urlsafe_b64decode(text + padding)
        return raw.decode("utf-8", errors="ignore").strip()
    except Exception:
        return ""

