# Scope: def _timelimit_for_days
def _timelimit_for_days(recency_days: int | None) -> str | None:
    if recency_days is None or recency_days <= 0:
        return None
    if recency_days <= 1:
        return "d"
    if recency_days <= 7:
        return "w"
    if recency_days <= 31:
        return "m"
    return "y"

