# Scope: def _contains_token
def _contains_token(text: str, token: str) -> bool:
    if token == "ai":
        return bool(re.search(r"\b(ai|a\.i\.|artificial intelligence)\b", text))
    return bool(re.search(rf"\b{re.escape(token)}\b", text))

