# File: service\service.py
# Scope: def check_auth_header
@app.middleware("http")
async def check_auth_header(request: Request, call_next):
    if _is_public_route(request.url.path):
        return await call_next(request)

    if ENABLE_USER_AUTH:
        auth_header = request.headers.get("Authorization")
        if not auth_header or not auth_header.startswith("Bearer "):
            return Response(status_code=401, content="Missing or invalid token")
        token = auth_header[7:].strip()
        user_id = _verify_access_token(token)
        if not user_id:
            return Response(status_code=401, content="Invalid or expired token")
        request.state.user_id = user_id
    else:
        if auth_secret := os.getenv("AUTH_SECRET"):
            auth_header = request.headers.get("Authorization")
            if not auth_header or not auth_header.startswith("Bearer "):
                return Response(status_code=401, content="Missing or invalid token")
            if auth_header[7:] != auth_secret:
                return Response(status_code=401, content="Invalid token")
    return await call_next(request)

# File: service\test_service.py
# Scope: def _auth_headers
def _auth_headers(c: TestClient, user_id: str | None = None, password: str = "Password123!"):
    user_id = user_id or f"test-user-{uuid4().hex[:8]}"
    register = c.post("/auth/register", json={"user_id": user_id, "password": password})
    if register.status_code == 409:
        login = c.post("/auth/login", json={"user_id": user_id, "password": password})
        assert login.status_code == 200
        token = login.json()["access_token"]
    else:
        assert register.status_code == 200
        token = register.json()["access_token"]
    return {"Authorization": f"Bearer {token}"}

